// Public RPC transport. Cache/Multicall stay above this layer. Retry only refused
// items: successful reads and contract reverts must never be replayed as a batch.
const TIMEOUT_MS = 10_000;
const RATE_START = 6, RATE_MAX = 8, RATE_MIN = 1, BURST = 3;
const PACING_MEMORY_MS = 90_000;
const MAX_RESTS = 4;
const QUEUE_AGE_MS = 10_000;
const states = new Set();
let listening = false;
let pendingSends = 0;

/** Optional warmups wait for queued reads, retries, and endpoint probes too. */
export function hasPendingRpcReads() {
  return pendingSends > 0 || [...states].some(state => state.primaryProbe != null);
}

export class RpcUnavailableError extends Error {
  constructor(retryAt) {
    super('Chain RPC unavailable right now; retrying shortly.');
    this.name = 'RpcUnavailableError';
    this.code = 'RPC_UNAVAILABLE';
    this.retryAt = retryAt;
  }
}

export function clearRpcOutages() {
  if (typeof document !== 'undefined' && document.visibilityState === 'hidden') return;
  for (const state of states) {
    state.outageUntil = 0;
    state.consecutiveOutages = 0;
    state.outageStartedAt = null;
  }
}

function listenForResume() {
  if (listening) return;
  listening = true;
  globalThis.document?.addEventListener?.('visibilitychange', clearRpcOutages);
  globalThis.window?.addEventListener?.('online', clearRpcOutages);
  globalThis.window?.addEventListener?.('pageshow', clearRpcOutages);
}

const wait = (ms, signal) => new Promise(resolve => {
  const finish = () => { clearTimeout(timer); signal?.removeEventListener('abort', finish); resolve(); };
  const timer = setTimeout(finish, ms);
  signal?.addEventListener('abort', finish, { once: true });
  if (signal?.aborted) finish();
});
const itemsOf = payload => Array.isArray(payload) ? payload : [payload];
export function rpcAbortError(signal) {
  if (signal?.reason instanceof Error) return signal.reason;
  const error = new Error('Read cancelled'); error.name = 'AbortError'; return error;
}
const cancelledRow = request => ({ jsonrpc: '2.0', id: request.id,
  error: { code: -32000, message: 'Read cancelled' } });
// A JSON-RPC batch can contain unrelated consumers. Only abort its HTTP/wait
// when every remaining item is abandoned; a surviving sibling owns the work.
function watchRequests(requests, signal, signals, changed = () => {}) {
  const controller = new AbortController();
  const active = request => !signal?.aborted && !signals?.get(request.id)?.aborted;
  const watched = new Set([signal, ...requests.map(request => signals?.get(request.id))].filter(Boolean));
  const update = () => {
    if (!requests.some(active)) controller.abort(rpcAbortError(signal?.aborted ? signal
      : [...watched].find(item => item.aborted)));
    changed();
  };
  for (const item of watched) item.addEventListener('abort', update);
  update();
  return { signal: controller.signal, active,
    dispose: () => { for (const item of watched) item.removeEventListener('abort', update); } };
}
function abortable(promise, signal) {
  if (!signal) return promise;
  return new Promise((resolve, reject) => {
    const abort = () => reject(rpcAbortError(signal));
    signal.addEventListener('abort', abort, { once: true });
    Promise.resolve(promise).then(resolve, reject).finally(() => signal.removeEventListener('abort', abort));
    if (signal.aborted) abort();
  });
}
const messageOf = item => String(item?.error?.message ?? '');
const rateLimited = item => [-32016, -32007].includes(Number(item?.error?.code))
  || /rate.?limit|too many requests|request limit/i.test(messageOf(item));
const historyMissing = item => Number(item?.error?.code) === 4444
  || /pruned history|missing trie node|historical (?:state|data).*?(?:unavailable|not available)|state.*?pruned/i.test(messageOf(item));
const unavailable = item => historyMissing(item) || Number(item?.error?.code) === -32601
  || /no available upstreams|header not found|unknown block|method (?:not found|not supported)/i.test(messageOf(item));
const batchLimited = item => /batch.*?(?:limit|not allowed|too (?:large|many)|maximum|exceed)/i.test(messageOf(item));
const MAX_CAPABILITY_REFUSALS = 256;
const methodMissing = item => Number(item?.error?.code) === -32601
  || /method (?:not found|not supported)/i.test(messageOf(item));

// Remember only recent provider feedback, never requests or chain answers.
// Storage already scopes the browser origin. Hash the full endpoint URL so
// private URLs stay isolated without putting their credentials in storage;
// changing routes/deployments must not erase the same provider's cooldown.
function pacingKey(url) {
  let hash = 0xcbf29ce484222325n;
  for (let i = 0; i < url.length; i++) {
    hash = BigInt.asUintN(64, (hash ^ BigInt(url.charCodeAt(i))) * 0x100000001b3n);
  }
  return `rpc-pacing:v1:${hash.toString(16).padStart(16, '0')}`;
}

function readPacing(key) {
  try {
    const raw = globalThis.localStorage?.getItem(key);
    if (!raw) return null;
    const saved = JSON.parse(raw), now = Date.now();
    if (!saved || !Number.isSafeInteger(saved.at) || saved.at < 0 || saved.at > now
      || !Number.isSafeInteger(saved.coolUntil) || saved.coolUntil < 0
      || !Number.isFinite(saved.rate) || saved.rate < RATE_MIN || saved.rate > RATE_START
      || !Number.isInteger(saved.burst) || saved.burst < 1 || saved.burst > BURST
      || !Number.isInteger(saved.maxBatch) || saved.maxBatch < 1 || saved.maxBatch > 10
      || Math.max(saved.at + PACING_MEMORY_MS, saved.coolUntil) <= now) {
      globalThis.localStorage?.removeItem(key);
      return null;
    }
    return saved;
  } catch { return null; } // Storage may be blocked, unavailable, or malformed.
}

function rememberPacing(endpoint, refusal = false) {
  if (refusal) endpoint.feedbackAt = Date.now();
  if (endpoint.feedbackAt == null) return;
  try {
    // Another tab/instance may have learned a newer refusal. An older success
    // or expiry cleanup must not erase its cooldown and let a reload bypass it.
    const saved = readPacing(endpoint.pacingKey);
    if (saved?.at > endpoint.feedbackAt) return;
    if (refusal) endpoint.coolUntil = Math.max(endpoint.coolUntil, saved?.coolUntil ?? 0);
    else if (saved && saved.coolUntil > Date.now() && saved.coolUntil > endpoint.coolUntil) return;
    if (Math.max(endpoint.feedbackAt + PACING_MEMORY_MS, endpoint.coolUntil) <= Date.now()) {
      globalThis.localStorage?.removeItem(endpoint.pacingKey);
      endpoint.feedbackAt = null;
      return;
    }
    globalThis.localStorage?.setItem(endpoint.pacingKey, JSON.stringify({
      at: endpoint.feedbackAt, coolUntil: endpoint.coolUntil,
      rate: Math.min(RATE_START, endpoint.rate), burst: endpoint.burst, maxBatch: endpoint.maxBatch,
    }));
  } catch { /* Optional pacing memory must never block a chain read. */ }
}

function requestBlockScope(request) {
  const params = request.params ?? [];
  switch (request.method) {
    case 'eth_call': case 'eth_getBalance': case 'eth_getCode': case 'eth_getTransactionCount':
      return params[1] ?? 'latest';
    case 'eth_getStorageAt': return params[2] ?? 'latest';
    case 'eth_getBlockByNumber': return params[0] ?? 'latest';
    case 'eth_getLogs': return params[0]?.blockHash
      ? { blockHash: params[0].blockHash }
      : [params[0]?.fromBlock ?? 'latest', params[0]?.toBlock ?? 'latest'];
    default: return params;
  }
}

function capabilityKey(request) {
  return `${request.method}:${JSON.stringify(requestBlockScope(request))}`;
}

function fixedBlockScope(scope) {
  if (Array.isArray(scope)) return scope.length > 0 && scope.every(fixedBlockScope);
  if (scope && typeof scope === 'object') return /^0x[0-9a-f]{64}$/i.test(scope.blockHash ?? '')
    || /^0x[0-9a-f]+$/i.test(scope.blockNumber ?? '');
  return /^0x[0-9a-f]+$/i.test(scope ?? '') || scope === 'earliest';
}

function cachedRefusal(endpoint, request) {
  for (const key of [request.method, capabilityKey(request)]) {
    if (endpoint.unavailableUntil.get(key) > Date.now()) return endpoint.unavailableErrors.get(key);
    endpoint.unavailableUntil.delete(key);
    endpoint.unavailableErrors.delete(key);
  }
  return null;
}

function rememberRefusal(endpoint, request, row) {
  // Unsupported methods are an endpoint capability. Missing archive state or
  // an unknown block proves nothing about current reads of that SAME method.
  // Scope those refusals to the requested block/range, including EIP-1898
  // hashes, so one old snapshot cannot divert all live traffic for five minutes.
  const key = methodMissing(row) ? request.method : capabilityKey(request);
  const ttl = historyMissing(row) && fixedBlockScope(requestBlockScope(request)) ? 300_000 : 12_000;
  endpoint.unavailableUntil.delete(key);
  endpoint.unavailableUntil.set(key, Date.now() + ttl);
  endpoint.unavailableErrors.set(key, row);
  while (endpoint.unavailableUntil.size > MAX_CAPABILITY_REFUSALS) {
    const oldest = endpoint.unavailableUntil.keys().next().value;
    endpoint.unavailableUntil.delete(oldest);
    endpoint.unavailableErrors.delete(oldest);
  }
}

function retryAfter(response) {
  const raw = response?.headers?.get?.('retry-after');
  if (!raw) return 0;
  const seconds = Number(raw);
  return Number.isFinite(seconds) ? Math.max(0, seconds * 1000)
    : Math.max(0, (Date.parse(raw) || 0) - Date.now());
}

function responseItems(json, requests, allowPartial = false) {
  const rows = itemsOf(json);
  if (rows.length !== requests.length && !(allowPartial && rows.length < requests.length)) {
    throw new Error('Incomplete JSON-RPC response.');
  }
  const byId = new Map();
  for (const row of rows) {
    if (!row || byId.has(row.id) || !requests.some(request => request.id === row.id)
      || (Object.hasOwn(row, 'result') === Object.hasOwn(row, 'error'))) {
      throw new Error('Invalid JSON-RPC response.');
    }
    byId.set(row.id, row);
  }
  return requests.map(request => byId.get(request.id));
}

// Only a same-origin relay may be configured here: its server/provider must
// enforce the actual account spending cap. These limits merely bound a page's
// emergency traffic; reloading a browser is not an account-wide budget.
const EMERGENCY_METHODS = new Set([
  'eth_chainId', 'eth_blockNumber', 'eth_call', 'eth_getBalance', 'eth_getCode',
  'eth_getStorageAt', 'eth_getTransactionReceipt', 'eth_getTransactionCount',
  'eth_estimateGas', 'eth_gasPrice', 'eth_feeHistory', 'eth_maxPriorityFeePerGas',
]);
function emergencyEligible(request) {
  if (EMERGENCY_METHODS.has(request.method)) return true;
  return request.method === 'eth_getBlockByNumber'
    && ['latest', 'pending', 'safe', 'finalized'].includes(request.params?.[0]);
}

export function makeRpcSend(urls, fetchImpl, timeoutMs = TIMEOUT_MS, waitImpl = wait, options = {}) {
  if (!urls.length) throw new Error('At least one free RPC is required.');
  const doFetch = fetchImpl ?? ((...args) => fetch(...args));
  const emergencyUrl = options.emergencyRpcUrl || '';
  if (emergencyUrl && !/^\/(?!\/)[a-z0-9/_-]+$/i.test(emergencyUrl)) {
    throw new Error('Emergency RPC must be a same-origin relay path.');
  }
  const state = {
    preferred: 0, consecutiveFailures: 0, outageUntil: 0, consecutiveOutages: 0,
    outageStartedAt: null, lastPrimaryProbeAt: 0, primaryProbe: null,
    emergencyRemaining: 300, emergencyWindowAt: Date.now(), emergencyWindowUsed: 0,
    endpoints: urls.map(url => {
      const key = pacingKey(url), saved = readPacing(key);
      return {
        coolUntil: saved?.coolUntil ?? 0, strikes: 0,
        rate: saved?.rate ?? RATE_START, burst: saved?.burst ?? BURST,
        // Reloading a recently refused endpoint grants no new burst credit.
        tokens: saved ? 0 : BURST, refillAt: Date.now(), maxBatch: saved?.maxBatch ?? 10,
        pacingKey: key, feedbackAt: saved?.at ?? null,
        unavailableUntil: new Map(), unavailableErrors: new Map(),
        queue: [], draining: false, wake: null,
      };
    }),
  };

  // Serialize admission, not HTTP. A purchase/claim read must not sit behind
  // every queued history scan. Priority changes order only: all callers still
  // spend the same tokens and honor the endpoint's Retry-After cooldown.
  const drain = async endpoint => {
    if (endpoint.draining) return;
    endpoint.draining = true;
    try {
      while (endpoint.queue.length) {
        // Live reads go first in a fresh queue. Let waiting work gain priority
        // so recurring live polls cannot indefinitely starve history or totals
        // under a throttled endpoint. Aging changes order, never rate limits.
        const now = Date.now();
        const score = entry => entry.priority + Math.floor(Math.max(0, now - entry.queuedAt) / QUEUE_AGE_MS);
        const entry = endpoint.queue.reduce((first, next) => score(next) > score(first) ? next : first);
        // Recompute after every wake: a queued ten-item batch may have been
        // admitted before another request taught us this RPC only tolerates one.
        const requests = [];
        let cost = 0;
        for (const request of entry.requests.filter(entry.active).slice(0, endpoint.maxBatch)) {
          const weight = request.method === 'eth_getLogs' ? 3 : 1;
          if (requests.length && cost + weight > endpoint.burst) break;
          requests.push(request);
          cost += weight;
        }
        if (!requests.length) {
          endpoint.queue.splice(endpoint.queue.indexOf(entry), 1);
          entry.resolve([]);
          continue;
        }
        endpoint.tokens = Math.min(endpoint.burst, endpoint.tokens + (now - endpoint.refillAt) / 1000 * endpoint.rate);
        endpoint.refillAt = now;
        // A weighted log request can cost more than a reduced burst capacity.
        // Admit it once the bucket is full, then charge its entire cost; the
        // resulting debt keeps the next read paced without starving history.
        const delay = Math.max(endpoint.coolUntil - now, Math.ceil((Math.min(cost, endpoint.burst) - endpoint.tokens) / endpoint.rate * 1000));
        if (delay <= 0) {
          endpoint.tokens -= cost;
          endpoint.queue.splice(endpoint.queue.indexOf(entry), 1);
          entry.resolve(requests);
          continue;
        }
        const wake = new AbortController();
        endpoint.wake = () => wake.abort();
        await waitImpl(delay, wake.signal);
        endpoint.wake = null;
      }
    } catch (error) {
      for (const entry of endpoint.queue.splice(0)) entry.reject(error);
    } finally {
      endpoint.wake = null;
      endpoint.draining = false;
    }
  };
  const acquire = (endpoint, requests, priority, signal, signals) => {
    return new Promise((resolve, reject) => {
      let entry, scope;
      const changed = () => {
        if (entry && !entry.requests.some(scope.active)) {
          const index = endpoint.queue.indexOf(entry);
          if (index >= 0) { endpoint.queue.splice(index, 1); entry.resolve([]); }
        }
        endpoint.wake?.();
      };
      scope = watchRequests(requests, signal, signals, changed);
      entry = { requests, active: scope.active,
        resolve: value => { scope.dispose(); resolve(value); },
        reject: error => { scope.dispose(); reject(error); },
        queuedAt: Date.now(),
        priority: priority === 'interaction' ? 2 : requests.every(r => r.method === 'eth_getLogs') ? 0 : 1,
      };
      endpoint.queue.push(entry);
      endpoint.wake?.();
      void drain(endpoint);
    });
  };
  const rest = (endpoint, response) => {
    endpoint.strikes += 1;
    endpoint.rate = Math.max(RATE_MIN, endpoint.rate / 2);
    // Backoff must never enlarge a bucket after the average rate has recovered.
    endpoint.burst = Math.min(endpoint.burst, Math.max(1, Math.floor(endpoint.rate)));
    endpoint.maxBatch = Math.min(endpoint.maxBatch, endpoint.burst);
    const delay = Math.min(15_000, 1000 * 2 ** Math.min(10, endpoint.strikes - 1));
    // Never jitter below the server's Retry-After deadline.
    endpoint.coolUntil = Math.max(endpoint.coolUntil,
      Date.now() + Math.max(retryAfter(response), Math.round(delay * (0.8 + Math.random() * 0.4))));
    endpoint.tokens = Math.min(0, endpoint.tokens);
    endpoint.refillAt = Date.now();
    rememberPacing(endpoint, true);
    endpoint.wake?.();
  };
  const post = async (url, requests, batch, timeout = timeoutMs, signal, signals) => {
    const controller = new AbortController();
    const scope = watchRequests(requests, signal, signals);
    const abort = () => controller.abort(rpcAbortError(scope.signal));
    scope.signal.addEventListener('abort', abort, { once: true });
    const timer = setTimeout(() => controller.abort(), timeout);
    try {
      if (scope.signal.aborted) throw rpcAbortError(scope.signal);
      const response = await abortable(doFetch(url, {
        method: 'POST', headers: { 'content-type': 'application/json' },
        body: JSON.stringify(batch ? requests : requests[0]), signal: controller.signal,
      }), scope.signal);
      let rows;
      try { rows = responseItems(await abortable(response.json(), scope.signal), requests, response.status === 429); }
      catch (error) { if (response.ok) throw error; }
      if (scope.signal.aborted) throw rpcAbortError(scope.signal);
      return { response, rows };
    } finally { clearTimeout(timer); scope.dispose(); scope.signal.removeEventListener('abort', abort); }
  };
  const recovered = () => {
    state.outageUntil = 0;
    state.consecutiveOutages = 0;
    state.outageStartedAt = null;
  };
  const probePrimary = () => {
    if (!state.preferred || state.primaryProbe || Date.now() - state.lastPrimaryProbeAt < 60_000) return;
    state.lastPrimaryProbeAt = Date.now();
    state.primaryProbe = (async () => {
      const requests = [{ jsonrpc: '2.0', id: 0, method: 'eth_blockNumber', params: [] }];
      try {
        await acquire(state.endpoints[0], requests);
        const { response, rows } = await post(urls[0], requests, false, 3000);
        if (response.status === 429 || rows?.some(rateLimited)) {
          rest(state.endpoints[0], response);
          return;
        }
        if (!response.ok || !/^0x[0-9a-f]+$/i.test(rows?.[0]?.result ?? '')) return;
        state.preferred = 0;
        state.consecutiveFailures = 0;
        recovered();
      } catch { /* The next interval can try again; live reads use the free fallback. */ }
      finally { state.primaryProbe = null; }
    })();
  };

  const emergency = async (requests, signal, signals) => {
    if (!emergencyUrl || state.consecutiveOutages < 3 || state.outageStartedAt == null
      || Date.now() - state.outageStartedAt < 30_000
      || globalThis.document?.visibilityState === 'hidden' || globalThis.navigator?.onLine === false) return [];
    if (Date.now() - state.emergencyWindowAt >= 60_000) {
      state.emergencyWindowAt = Date.now(); state.emergencyWindowUsed = 0;
    }
    const allowed = requests.filter(request => !signal?.aborted && !signals?.get(request.id)?.aborted)
      .filter(emergencyEligible).slice(0,
      Math.max(0, Math.min(state.emergencyRemaining, 30 - state.emergencyWindowUsed)));
    if (!allowed.length) return [];
    // Spend before awaiting, so concurrent callers cannot overshoot these limits.
    state.emergencyRemaining -= allowed.length;
    state.emergencyWindowUsed += allowed.length;
    try {
      const { response, rows } = await post(emergencyUrl, allowed, true, 3000, signal, signals);
      return response.ok ? (rows ?? []) : [];
    } catch { return []; }
    // Paid success never changes free preference or clears the free probe timer.
  };

  const send = async (payload, { priority, signal, signals } = {}) => {
    const original = itemsOf(payload);
    if (signal?.aborted) throw rpcAbortError(signal);
    if (new Set(original.map(r => r.id)).size !== original.length) throw new Error('JSON-RPC request IDs must be unique.');
    const answers = new Map(), refused = new Map();
    const retireAbandoned = () => {
      if (signal?.aborted) throw rpcAbortError(signal);
      for (const request of original) if (signals?.get(request.id)?.aborted) {
        answers.set(request.id, cancelledRow(request));
      }
    };
    const finish = error => {
      retireAbandoned();
      if (!answers.size && !refused.size) throw error;
      return original.map(r => answers.get(r.id) ?? refused.get(r.id) ?? {
        jsonrpc: '2.0', id: r.id, error: { code: -32000, message: error.message },
      });
    };
    if (Date.now() < state.outageUntil) {
      for (const row of await emergency(original, signal, signals)) answers.set(row.id, row);
      return finish(new RpcUnavailableError(state.outageUntil));
    }
    retireAbandoned();
    if (answers.size === original.length) return finish();
    probePrimary();
    const failed = new Set();
    const start = state.preferred;
    let lastError = new RpcUnavailableError(Date.now() + 2000), rests = 0, refusals = 0, reachable = false;
    while (answers.size < original.length) {
      retireAbandoned();
      if (answers.size === original.length) break;
      const pending = original.filter(r => !answers.has(r.id));
      let index = -1, soonest = Infinity, requests;
      for (let n = 0; n < urls.length; n++) {
        const candidate = (start + n) % urls.length;
        if (failed.has(candidate)) continue;
        const endpoint = state.endpoints[candidate];
        const usable = pending.filter(r => {
          const previous = cachedRefusal(endpoint, r);
          if (!previous) return true;
          reachable = true;
          refused.set(r.id, { ...previous, id: r.id });
          return false;
        });
        if (!usable.length) continue;
        if (endpoint.coolUntil <= Date.now()) {
          index = candidate; requests = usable.slice(0, endpoint.maxBatch); break;
        }
        soonest = Math.min(soonest, endpoint.coolUntil);
      }
      if (index < 0) {
        if (soonest === Infinity || rests >= MAX_RESTS) break;
        rests += 1;
        const scope = watchRequests(pending, signal, signals);
        try { await abortable(waitImpl(Math.max(0, soonest - Date.now()), scope.signal), scope.signal); }
        catch (error) { if (!scope.signal.aborted) throw error; }
        finally { scope.dispose(); }
        continue;
      }
      const endpoint = state.endpoints[index];
      try {
        requests = await acquire(endpoint, requests, priority, signal, signals);
        retireAbandoned();
        requests = requests.filter(request => !answers.has(request.id));
        if (!requests.length) continue;
        const { response, rows } = await post(urls[index], requests, Array.isArray(payload), timeoutMs, signal, signals);
        retireAbandoned();
        if (response.status === 429 && !rows) {
          rest(endpoint, response); lastError = new Error(`HTTP 429 from ${urls[index]}`);
          if (++refusals >= (MAX_RESTS + 1) * urls.length) break;
          continue;
        }
        if ((response.status === 413 || rows?.every(batchLimited)) && requests.length > 1) {
          endpoint.maxBatch = Math.max(1, Math.floor(requests.length / 2));
          rememberPacing(endpoint, true);
          continue;
        }
        // Some providers wrap valid JSON-RPC errors in HTTP 400/500. Preserve
        // range/parameter errors for the scanner and block-hash fallback; a
        // contract revert must not become a transport outage either.
        if (!response.ok && !rows) {
          throw new Error(`HTTP ${response.status} from ${urls[index]}`);
        }
        let limited = response.status === 429;
        for (let n = 0; n < rows.length; n++) {
          const row = rows[n], request = requests[n];
          if (answers.has(request.id)) continue;
          if (!row) { limited = true; continue; }
          if (rateLimited(row)) { limited = true; continue; }
          reachable = true;
          if (unavailable(row)) {
            refused.set(row.id, row);
            rememberRefusal(endpoint, request, row);
            continue;
          }
          answers.set(row.id, row);
        }
        if (limited) {
          rest(endpoint, response); lastError = new Error(response.status === 429
            ? `HTTP 429 from ${urls[index]}` : `Rate limited by ${urls[index]}`);
          if (++refusals >= (MAX_RESTS + 1) * urls.length) break;
        } else {
          endpoint.strikes = 0;
          endpoint.rate = Math.min(RATE_MAX, endpoint.rate + 0.1);
          rememberPacing(endpoint);
          if (index === state.preferred) state.consecutiveFailures = 0;
        }
      } catch (error) {
        retireAbandoned();
        // Consumer cancellation says nothing about provider availability. If
        // the current HTTP chunk lost every consumer, continue with any other
        // still-live items without failover or an outage strike.
        if (requests.every(request => signals?.get(request.id)?.aborted)) continue;
        lastError = error;
        failed.add(index);
        if (index === state.preferred && ++state.consecutiveFailures >= 3) {
          state.preferred = (state.preferred + 1) % urls.length;
          state.consecutiveFailures = 0;
          state.lastPrimaryProbeAt = Date.now();
        }
      }
    }
    retireAbandoned();
    if (answers.size === original.length && original.every(request => signals?.get(request.id)?.aborted)) return finish();
    if (reachable) {
      recovered();
      return finish(lastError);
    }
    state.outageStartedAt ??= Date.now();
    state.consecutiveOutages += 1;
    const delay = Math.min(30_000, 2000 * 2 ** Math.min(10, state.consecutiveOutages - 1));
    state.outageUntil = Date.now() + Math.round(delay * (0.8 + Math.random() * 0.4));
    for (const row of await emergency(original.filter(r => !answers.has(r.id)), signal, signals)) answers.set(row.id, row);
    return finish(lastError);
  };
  const trackedSend = async (...args) => {
    pendingSends += 1;
    try { return await send(...args); }
    finally { pendingSends -= 1; }
  };
  trackedSend._state = state;
  states.add(state);
  listenForResume();
  return trackedSend;
}
